_LAND = zlib.decompress(base64.b64decode(LAND_B64))


def is_land(lat, lon):
    i = int((lon + 180.0) / 360.0 * MAP_W)
    j = int((90.0 - lat) / 180.0 * MAP_H)
    if i < 0 or i >= MAP_W or j < 0 or j >= MAP_H:
        return False
    idx = j * MAP_W + i
    return bool(_LAND[idx >> 3] & (0x80 >> (idx & 7)))


