_GEO = {'ready': False, 's4': None, 'c4': None, 's6': None, 'c6': None}


def _geo_load():
    """Rebuild the range tables. ~0.4s, so it runs off-thread at startup."""
    def unpack(blob_s, blob_c, width):
        d = array.array(width)
        d.frombytes(zlib.decompress(base64.b64decode(blob_s)))
        if sys.byteorder != 'little':
            d.byteswap()
        return list(itertools.accumulate(d)), zlib.decompress(base64.b64decode(blob_c))

    _GEO['s4'], _GEO['c4'] = unpack(GEO4_S, GEO4_C, 'I')
    _GEO['s6'], _GEO['c6'] = unpack(GEO6_S, GEO6_C, 'Q')
    _GEO['ready'] = True


def ip_to_int(ip):
    """-> (int, is_v6) or (None, None) if unparseable."""
    try:
        if ':' in ip:
            return int.from_bytes(socket.inet_pton(socket.AF_INET6, ip), 'big'), True
        return int.from_bytes(socket.inet_pton(socket.AF_INET, ip), 'big'), False
    except OSError:
        return None, None


def ip_country(ip):
    """Country code for an IP, or None while the table is still loading."""
    if not _GEO['ready']:
        return None
    n, v6 = ip_to_int(ip)
    if n is None:
        return '??'
    if v6:
        k = bisect.bisect_right(_GEO['s6'], n >> 64) - 1
        if k < 0:
            return '??'
        return GEO6_CODES[_GEO['c6'][k] * 2:_GEO['c6'][k] * 2 + 2]
    k = bisect.bisect_right(_GEO['s4'], n) - 1
    if k < 0:
        return '??'
    return GEO4_CODES[_GEO['c4'][k] * 2:_GEO['c4'][k] * 2 + 2]


def is_private(ip):
    n, v6 = ip_to_int(ip)
    if n is None:
        return True
    if v6:
        if n == 1:                                   # ::1
            return True
        top = n >> 112
        return (top & 0xFE00) == 0xFC00 or (top & 0xFFC0) == 0xFE80
    return (n >> 24 == 10 or n >> 24 == 127 or
            (n >> 20) == 0xAC1 or (n >> 16) == 0xC0A8 or
            (n >> 22) == 0x2B010 or n >> 24 == 0 or n >> 24 >= 224)


