# --- ANSI -----------------------------------------------------------------
ESC = '\033['
HIDE, SHOW = ESC + '?25l', ESC + '?25h'
HOME, CLEAR = ESC + 'H', ESC + '2J'
RESET = ESC + '0m'

_SGR = {}


def sgr(rgb):
    s = _SGR.get(rgb)
    if s is None:
        s = f'{ESC}38;2;{rgb[0]};{rgb[1]};{rgb[2]}m'
        _SGR[rgb] = s
    return s


def lerp(c0, c1, t):
    if t < 0.0:
        t = 0.0
    elif t > 1.0:
        t = 1.0
    return (int(c0[0] + (c1[0] - c0[0]) * t),
            int(c0[1] + (c1[1] - c0[1]) * t),
            int(c0[2] + (c1[2] - c0[2]) * t))


def quant(rgb, step=12):
    """Snap colours to a coarse ladder so the SGR cache stays small."""
    return (rgb[0] // step * step, rgb[1] // step * step, rgb[2] // step * step)


def scale(rgb, f):
    return (min(255, int(rgb[0] * f)), min(255, int(rgb[1] * f)),
            min(255, int(rgb[2] * f)))


# --- keyboard -------------------------------------------------------------
class Keyboard:
    """Non-blocking raw-mode key reader. No-ops when stdin isn't a tty."""

    def __init__(self):
        self.fd = None
        self.old = None
        self.termios = None
        if not sys.stdin.isatty():
            return
        try:
            import termios, tty
            self.termios = termios
            self.fd = sys.stdin.fileno()
            self.old = termios.tcgetattr(self.fd)
            tty.setcbreak(self.fd)
        except Exception:
            self.fd = None

    def restore(self):
        if self.fd is not None and self.old is not None:
            try:
                self.termios.tcsetattr(self.fd, self.termios.TCSADRAIN, self.old)
            except Exception:
                pass

    def poll(self):
        if self.fd is None:
            return []
        keys = []
        while select.select([sys.stdin], [], [], 0)[0]:
            try:
                data = os.read(self.fd, 64)
            except OSError:
                break
            if not data:
                break
            keys.extend(self._parse(data.decode('utf-8', 'ignore')))
            if len(keys) > 32:
                break
        return keys

    @staticmethod
    def _parse(s):
        out, i = [], 0
        arrows = {'A': 'UP', 'B': 'DOWN', 'C': 'RIGHT', 'D': 'LEFT'}
        while i < len(s):
            if s[i] == '\x1b':
                if s[i + 1:i + 2] == '[':
                    out.append(arrows.get(s[i + 2:i + 3], 'ESC'))
                    i += 3
                else:
                    # a bare Escape: previously fell through and was emitted
                    # as a raw \x1b, so nothing ever matched 'ESC'
                    out.append('ESC')
                    i += 1
            else:
                out.append(s[i])
                i += 1
        return out


# --- where am I -----------------------------------------------------------
def tz_latlon():
    """Home coordinates from the system timezone, via tzdata's zone.tab."""
    try:
        name = None
        link = os.path.realpath('/etc/localtime')
        if 'zoneinfo' in link:
            parts = link.split('zoneinfo/')[-1].split('/')
            if parts and parts[0] not in ('posix', 'right'):
                name = '/'.join(parts)
        name = os.environ.get('TZ') or name
        if not name:
            return None
        for path in ('/usr/share/zoneinfo/zone.tab',
                     '/usr/share/zoneinfo/zone1970.tab'):
            if not os.path.exists(path):
                continue
            with open(path) as fh:
                for line in fh:
                    if line.startswith('#'):
                        continue
                    col = line.split('\t')
                    if len(col) < 3 or col[2].strip() != name:
                        continue
                    return iso6709(col[1])
    except Exception:
        pass
    return None


def iso6709(s):
    """'+512830-0001845' -> (51.475, -0.3125)"""
    m = re.match(r'([+-]\d{2})(\d{2})(\d{2})?([+-]\d{3})(\d{2})(\d{2})?$', s)
    if not m:
        return None
    la = float(m.group(1)) + int(m.group(2)) / 60.0 + int(m.group(3) or 0) / 3600.0
    lo = float(m.group(4)) + int(m.group(5)) / 60.0 + int(m.group(6) or 0) / 3600.0
    # the degrees field carries the sign; minutes/seconds must follow it
    if m.group(1).startswith('-'):
        la = float(m.group(1)) - int(m.group(2)) / 60.0 - int(m.group(3) or 0) / 3600.0
    if m.group(4).startswith('-'):
        lo = float(m.group(4)) - int(m.group(5)) / 60.0 - int(m.group(6) or 0) / 3600.0
    return la, lo


# --- sun ------------------------------------------------------------------
def subsolar(t):
    """Low-precision subsolar point (lat, lon) for a unix timestamp."""
    d = t / 86400.0 + 2440587.5 - 2451545.0
    g = math.radians((357.529 + 0.98560028 * d) % 360.0)
    q = (280.459 + 0.98564736 * d) % 360.0
    L = math.radians((q + 1.915 * math.sin(g) + 0.020 * math.sin(2 * g)) % 360.0)
    e = math.radians(23.439 - 0.00000036 * d)
    dec = math.asin(math.sin(e) * math.sin(L))
    ra = math.atan2(math.cos(e) * math.sin(L), math.cos(L))
    gmst = (18.697374558 + 24.06570982441908 * d) % 24.0
    lon = ((math.degrees(ra) - gmst * 15.0) + 180.0) % 360.0 - 180.0
    return math.degrees(dec), lon


def sun_alt(lat, lon, sdec, slon):
    """Sine of solar altitude -- >0 is daylight."""
    la, sd = math.radians(lat), math.radians(sdec)
    h = math.radians(lon - slon)
    return math.sin(la) * math.sin(sd) + math.cos(la) * math.cos(sd) * math.cos(h)


# --- connection sampling --------------------------------------------------
# `ss -tuanpi` rows: netid state recv-q send-q local peer [process]
SS_RE = re.compile(r'^(tcp|udp)\s+(\S+)\s+(\d+)\s+(\d+)\s+(\S+)\s+(\S+)\s*(.*)$')
PROC_RE = re.compile(r'\(\("([^"]+)",pid=(\d+)')


def split_hostport(tok):
    """'10.0.0.1%wlan0:68' / '[fe80::1]%eth0:546' / '0.0.0.0:*' -> (ip, port).

    Port is None when the socket has no concrete peer, which is how a
    listener is told apart from a connection.
    """
    if ':' not in tok:
        return tok, None
    host, _, port = tok.rpartition(':')
    host = host.split('%')[0]           # drop the scope id before unbracketing
    if host.startswith('[') and host.endswith(']'):
        host = host[1:-1]
    return host, (int(port) if port.isdigit() else None)
BS_RE = re.compile(r'bytes_sent:(\d+)')
BR_RE = re.compile(r'bytes_received:(\d+)')
RTT_RE = re.compile(r'\brtt:([\d.]+)')


def strip_br(a):
    return a[1:-1] if a.startswith('[') else a


class Sampler(threading.Thread):
    """Polls `ss` (or /proc/net/tcp) on a timer. Main loop just reads .snap."""

    daemon = True

    def __init__(self, period=1.5, demo=False, remote=None):
        super().__init__()
        self.period = period
        self.demo = demo
        self.remote = remote
        self.snap = {}
        self.lock = threading.Lock()
        self.err = None
        self.method = 'demo' if demo else None
        self._stop = threading.Event()
        self._nudge = threading.Event()
        self._demo_state = {}

    def stop(self):
        self._stop.set()
        self._nudge.set()

    def nudge(self):
        """Ask for a scan right now instead of waiting out the period."""
        self._nudge.set()

    def run(self):
        while not self._stop.is_set():
            try:
                snap = self._demo_sample() if self.demo else self._sample()
                with self.lock:
                    self.snap = snap
            except Exception as exc:                 # never kill the UI
                self.err = f'{type(exc).__name__}: {exc}'
            self._nudge.wait(self.period)
            self._nudge.clear()

    def get(self):
        with self.lock:
            return self.snap

    def _sample(self):
        cmd = ['ss', '-tuanpi']
        if self.remote:
            cmd = ['ssh', '-o', 'BatchMode=yes', '-o', 'ConnectTimeout=6',
                   self.remote, 'ss -tuanpi']
        try:
            pr = subprocess.run(cmd, capture_output=True, text=True,
                                timeout=20 if self.remote else 6)
            if not pr.stdout.strip():
                msg = (pr.stderr or 'no output from ss').strip()
                raise OSError(msg.splitlines()[-1][:100] if msg else 'no output')
            self.method = ('ssh ' + self.remote.split('@')[-1]) if self.remote \
                else 'ss'
            self.err = None
            return self._parse_ss(pr.stdout)
        except (FileNotFoundError, subprocess.TimeoutExpired, OSError) as exc:
            if self.remote:                 # no local fallback makes sense
                self.err = str(exc)
                self.method = 'ssh?'
                return {}
            self.method = 'proc'
            return self._parse_proc()

    @staticmethod
    def _parse_ss(out):
        """Rows -> {key: conn}. Two passes: listeners first, so a connection
        arriving on a port we listen on can be marked inbound."""
        recs = []
        listen = set()
        cur = None
        for line in out.splitlines():
            if line.startswith((' ', '\t')):          # continuation: tcp_info
                if cur is not None:
                    m = BS_RE.search(line)
                    if m:
                        cur['tx'] = int(m.group(1))
                    m = BR_RE.search(line)
                    if m:
                        cur['rx'] = int(m.group(1))
                    m = RTT_RE.search(line)
                    if m:
                        cur['rtt'] = float(m.group(1))
                continue
            cur = None
            m = SS_RE.match(line.strip())
            if not m:
                continue
            proto, state, _rq, _sq, la, ra, rest = m.groups()
            lip, lport = split_hostport(la)
            rip, rport = split_hostport(ra)
            if lport is None:
                continue
            # no concrete peer -> it's a listener, not a conversation
            if state == 'LISTEN' or rport is None or rip in ('0.0.0.0', '::', '*'):
                listen.add((proto, lport))
                continue
            pm = PROC_RE.search(rest)
            rec = {'state': state, 'ip': rip, 'port': rport, 'lport': lport,
                   'lip': lip, 'proto': proto,
                   'proc': pm.group(1) if pm else '?',
                   'pid': int(pm.group(2)) if pm else 0,
                   'tx': 0, 'rx': 0, 'rtt': 0.0, 'inbound': False}
            recs.append(rec)
            cur = rec
        conns = {}
        for rec in recs:
            rec['inbound'] = (rec['proto'], rec['lport']) in listen
            conns[(rec['proto'], rec['lip'], rec['lport'],
                   rec['ip'], rec['port'])] = rec
        return conns

    @staticmethod
    def _parse_proc():
        """Fallback when ss is missing: no process names, no byte counters."""
        states = {'01': 'ESTAB', '02': 'SYN-SENT', '03': 'SYN-RECV',
                  '04': 'FIN-WAIT-1', '05': 'FIN-WAIT-2', '06': 'TIME-WAIT',
                  '08': 'CLOSE-WAIT', '09': 'LAST-ACK', '0B': 'CLOSING'}
        conns = {}
        for path, v6 in (('/proc/net/tcp', False), ('/proc/net/tcp6', True)):
            try:
                lines = open(path).read().splitlines()[1:]
            except OSError:
                continue
            for line in lines:
                f = line.split()
                if len(f) < 4:
                    continue
                st = states.get(f[3])
                if st is None:
                    continue
                try:
                    la, lp = f[1].rsplit(':', 1)
                    ra, rp = f[2].rsplit(':', 1)
                    lip, rip = hex_ip(la, v6), hex_ip(ra, v6)
                    lpi, rpi = int(lp, 16), int(rp, 16)
                except ValueError:
                    continue
                conns[('tcp', lip, lpi, rip, rpi)] = {
                    'state': st, 'ip': rip, 'port': rpi, 'lport': lpi,
                    'lip': lip, 'proto': 'tcp', 'proc': '?', 'pid': 0,
                    'tx': 0, 'rx': 0, 'rtt': 0.0, 'inbound': False}
        return conns

    def _demo_sample(self):
        """Synthetic traffic so the map has something to draw when offline.

        Connections persist between samples and churn slowly, so the map looks
        like a real session rather than reshuffling every scan.
        """
        pool = ['13.107.42.14', '142.250.187.206', '104.18.34.205',
                '151.101.129.91', '18.97.36.61', '203.0.113.7', '91.198.174.192',
                '210.140.92.183', '200.160.2.3', '196.216.2.1', '1.1.1.1',
                '31.13.72.36', '5.9.10.11', '103.21.244.1', '185.199.108.153']
        procs = ['firefox', 'curl', 'ssh', 'nc', 'python3', 'chromium']
        ports = [443, 443, 443, 443, 80, 22, 53, 9050, 6667]
        rng = random.Random()
        st = self._demo_state
        if not st:
            st['n'] = 0
            st['conns'] = {}
        conns = st['conns']
        while len(conns) < 6 or (len(conns) < 16 and rng.random() < 0.35):
            st['n'] += 1
            ip = rng.choice(pool)
            key = (rng.choice(('tcp', 'tcp', 'tcp', 'udp')), '10.0.0.2',
                   40000 + st['n'], ip, rng.choice(ports))
            conns[key] = {'proc': rng.choice(procs), 'tx': 0, 'rx': 0,
                          'pid': 1000 + rng.randrange(9000),
                          'rtt': rng.uniform(4, 180),
                          'inbound': rng.random() < 0.25,
                          'burst': rng.random() < 0.4}
        if len(conns) > 6 and rng.random() < 0.25:
            del conns[rng.choice(list(conns))]
        out = {}
        for key, c in conns.items():
            proto, local, lport, ip, port = key
            if c['burst']:
                c['tx'] += rng.randint(0, 40000)
                c['rx'] += rng.randint(0, 500000)
            out[key] = {'state': 'ESTAB', 'ip': ip, 'port': port, 'lport': lport,
                        'lip': local, 'proto': proto, 'proc': c['proc'],
                        'pid': c['pid'], 'inbound': c['inbound'],
                        'tx': c['tx'], 'rx': c['rx'], 'rtt': c['rtt']}
        return out


def hex_ip(h, v6):
    if not v6:
        b = bytes.fromhex(h)[::-1]
        return socket.inet_ntop(socket.AF_INET, b)
    # /proc stores v6 as four little-endian 32-bit words
    w = [bytes.fromhex(h[i:i + 8])[::-1] for i in range(0, 32, 8)]
    return socket.inet_ntop(socket.AF_INET6, b''.join(w))


# --- reverse DNS ----------------------------------------------------------
class Resolver:
    """Best-effort rDNS on a couple of daemon threads, with a cache."""

    def __init__(self, workers=3, enabled=True):
        self.cache = {}
        self.enabled = enabled
        self.q = []
        self.seen = set()
        self.lock = threading.Lock()
        self.ev = threading.Event()
        for _ in range(workers):
            threading.Thread(target=self._work, daemon=True).start()

    def get(self, ip):
        """Hostname, '' if the host has no PTR record, None while pending."""
        if not self.enabled:
            return None
        v = self.cache.get(ip)
        if v is not None:
            return v
        with self.lock:
            if ip not in self.seen:
                self.seen.add(ip)
                self.q.append(ip)
                self.ev.set()
        return None

    def _work(self):
        while True:
            self.ev.wait(0.5)
            with self.lock:
                ip = self.q.pop(0) if self.q else None
                if not self.q:
                    self.ev.clear()
            if ip is None:
                continue
            try:
                name = socket.gethostbyaddr(ip)[0]
            except Exception:
                name = ''
            self.cache[ip] = name


# --- model ----------------------------------------------------------------
class Endpoint:
    __slots__ = ('ip', 'cc', 'lat', 'lon', 'first', 'last', 'conns', 'tx', 'rx',
                 'rate_tx', 'rate_rx', 'rtt', 'procs', 'ports', 'alive', 'flash',
                 'protos', 'inbound')

    def __init__(self, ip, now):
        self.ip = ip
        self.cc = None
        self.lat = self.lon = None
        self.first = self.last = now
        self.conns = 0
        self.tx = self.rx = 0
        self.rate_tx = self.rate_rx = 0.0
        self.rtt = 0.0
        self.procs = set()          # {(process name, pid)}
        self.ports = set()
        self.protos = set()
        self.inbound = False
        self.alive = True
        self.flash = 1.0


def place(ip, cc):
    """Country centroid + deterministic scatter, so dots don't all stack."""
    ent = CENTROIDS.get(cc)
    if ent is None:
        return None
    lat, lon = ent[0], ent[1]
    h = zlib.crc32(ip.encode())
    lat += ((h & 0xFF) / 255.0 - 0.5) * 5.0
    lon += (((h >> 8) & 0xFF) / 255.0 - 0.5) * 7.0
    return max(-85.0, min(85.0, lat)), ((lon + 180.0) % 360.0) - 180.0


def bps(n):
    for unit, div in (('G', 1e9), ('M', 1e6), ('K', 1e3)):
        if n >= div:
            return f'{n / div:5.1f}{unit}'
    return f'{n:5.0f} '


def size(n):
    """Cumulative volume, in bytes (bps() is for rates, in bits)."""
    for unit, div in (('T', 1e12), ('G', 1e9), ('M', 1e6), ('K', 1e3)):
        if n >= div:
            return f'{n / div:.1f}{unit}B'
    return f'{int(n)}B'


def fmt_dur(s):
    s = int(s)
    if s < 60:
        return f'{s}s'
    if s < 3600:
        return f'{s // 60}m{s % 60:02d}'
    return f'{s // 3600}h{(s % 3600) // 60:02d}'


# --- great-circle ---------------------------------------------------------
def to_vec(lat, lon):
    la, lo = math.radians(lat), math.radians(lon)
    c = math.cos(la)
    return c * math.cos(lo), c * math.sin(lo), math.sin(la)


def to_ll(v):
    return (math.degrees(math.asin(max(-1.0, min(1.0, v[2])))),
            math.degrees(math.atan2(v[1], v[0])))


def gc_path(a, b, n):
    """n samples along the great circle from (lat,lon) a to b."""
    va, vb = to_vec(*a), to_vec(*b)
    dot = max(-1.0, min(1.0, sum(x * y for x, y in zip(va, vb))))
    om = math.acos(dot)
    out = []
    if om < 1e-6:
        return [a]
    so = math.sin(om)
    for i in range(n + 1):
        t = i / n
        s0, s1 = math.sin((1 - t) * om) / so, math.sin(t * om) / so
        out.append(to_ll(tuple(s0 * x + s1 * y for x, y in zip(va, vb))))
    return out


_LAND_CACHE = {}


def land_raster(uw, uh):
    """Per-cell land coverage for a given map size, plus per-row/col trig.

    Only depends on the map dimensions, so it survives every frame until the
    terminal is resized -- the per-frame loop then does no is_land() calls and
    no trigonometry beyond one multiply per lit cell.
    """
    key = (uw, uh)
    hit = _LAND_CACHE.get(key)
    if hit is not None:
        return hit
    if len(_LAND_CACHE) > 8:
        _LAND_CACHE.clear()
    grid = []
    for j in range(uh):
        lat0 = 90.0 - j / uh * 180.0
        lat1 = 90.0 - (j + 1) / uh * 180.0
        lats = (lat0 * 0.75 + lat1 * 0.25, lat0 * 0.25 + lat1 * 0.75)
        cells = []
        for i in range(uw):
            lon0 = i / uw * 360.0 - 180.0
            lon1 = (i + 1) / uw * 360.0 - 180.0
            lons = (lon0 * 0.75 + lon1 * 0.25, lon0 * 0.25 + lon1 * 0.75)
            n = sum(1 for la in lats for lo in lons if is_land(la, lo))
            if n:
                cells.append((i, n * 0.25))
        la = math.radians((lat0 + lat1) * 0.5)
        grid.append((math.sin(la), math.cos(la), cells))
    lons = [math.radians((i + 0.5) / uw * 360.0 - 180.0) for i in range(uw)]
    hit = (grid, [math.cos(x) for x in lons], [math.sin(x) for x in lons])
    _LAND_CACHE[key] = hit
    return hit


HELP_LINES = [
    '',
    '  NETMAP -- live connection cartography',
    '',
    '  SPACE  freeze / resume        q  quit',
    '  h / ?  this panel             r  force a re-scan now',
    '',
    '  p      cycle palette          1-5  palette direct',
    '  n      day/night terminator   g    glitch',
    '  a      arcs                   k    packet flow',
    '  d      reverse DNS lookups    l    endpoint labels',
    '  s      hide/show sidebar      e    hide/show event log',
    '  m      include private/LAN peers',
    '  z      zen mode (map only)',
    '',
    '  UP/DOWN  select an endpoint (list holds still 3s)',
    '  ESC / x  clear the selection',
    '  LEFT/RIGHT  sort: traffic (rate now) / volume',
    '              (session total) / recent / latency /',
    '              country / process (app then pid)',
    '',
    '  Log: > out  < in  x closed  ~ rDNS  ! notable',
    '',
    '  OPEN ▁▂▄█ under the map is the open-connection count,',
    '  one bar per scan, brightening with height.',
    '',
    '  Geolocation is country-level: a dot marks the country,',
    '  not a street. Scatter within a country is cosmetic.',
    '',
]


SORTS = ['traffic', 'volume', 'recent', 'latency', 'country', 'process']


def main():
    ap = argparse.ArgumentParser(
        description='Live network topology map for the terminal.',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog='Geolocation is country-level. Press h in-app for key bindings.')
    ap.add_argument('--palette', choices=PAL_NAMES, default='matrix')
    ap.add_argument('--fps', type=float, default=30.0)
    ap.add_argument('--interval', type=float, default=1.5,
                    help='seconds between connection scans (default 1.5)')
    ap.add_argument('--home', metavar='LAT,LON',
                    help='your coordinates; default is guessed from $TZ')
    ap.add_argument('--remote', metavar='[USER@]HOST',
                    help='map a remote machine over SSH instead of this one '
                         '(needs key-based login and ss on the far end)')
    ap.add_argument('--no-udp', action='store_true',
                    help='TCP only; by default UDP/QUIC peers are included')
    ap.add_argument('--demo', action='store_true',
                    help='synthetic traffic instead of real connections')
    ap.add_argument('--private', action='store_true',
                    help='also plot LAN/loopback peers')
    ap.add_argument('--no-dns', action='store_true', help='skip reverse DNS')
    ap.add_argument('--no-night', action='store_true')
    ap.add_argument('--no-arcs', action='store_true')
    ap.add_argument('--no-glitch', action='store_true')
    ap.add_argument('--no-sidebar', action='store_true')
    ap.add_argument('--no-log', action='store_true')
    ap.add_argument('--no-labels', action='store_true')
    ap.add_argument('--zen', action='store_true', help='map only, no chrome')
    args = ap.parse_args()

    home = None
    if args.home:
        try:
            la, lo = args.home.split(',')
            home = (float(la), float(lo))
        except ValueError:
            sys.exit('--home wants LAT,LON e.g. 51.5,-0.13')
    if home is None and args.remote:
        # put the home marker on the machine we're actually watching
        host = args.remote.split('@')[-1]
        try:
            ip = socket.getaddrinfo(host, None)[0][4][0]
            _geo_load()
            pos = place(ip, ip_country(ip) or '')
            if pos:
                home = pos
        except Exception:
            pass
    if home is None:
        home = tz_latlon() or (51.5, -0.13)

    pal = args.palette
    show = {'night': not args.no_night, 'arcs': not args.no_arcs,
            'glitch': not args.no_glitch, 'sidebar': not args.no_sidebar,
            'log': not args.no_log, 'labels': not args.no_labels,
            'dns': not args.no_dns, 'packets': True,
            'private': args.private}
    if args.zen:
        show['sidebar'] = show['log'] = show['labels'] = False

    kbd = Keyboard()
    threading.Thread(target=_geo_load, daemon=True).start()
    res = Resolver(enabled=show['dns'])
    smp = Sampler(period=max(0.3, args.interval), demo=args.demo,
                  remote=args.remote)
    smp.start()

    def cleanup(*_):
        smp.stop()
        kbd.restore()
        sys.stdout.write(SHOW + RESET + CLEAR + HOME)
        sys.stdout.flush()
        os._exit(0)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    sys.stdout.write(HIDE + CLEAR)

    eps = {}                 # ip -> Endpoint
    prev_counters = {}       # conn key -> (tx, rx)
    log = []                 # (t, kind, text, tone)
    packets = []
    paths = {}               # ip -> (key, [(lat,lon)...])
    started = time.time()
    last_sample_id = None
    last_rates = 0.0
    tot_tx = tot_rx = 0.0
    hist = []                # (t, conns) for the sparkline
    sel = None
    sort = 0
    ordered = []
    rowdata = []           # what the sidebar is currently showing
    held_rows = []         # frozen copy taken when you start arrowing
    hold_until = 0.0
    seen_ccs = set()
    named = set()
    burst_at = {}
    peak_rx = peak_tx = 0.0
    first_scan = True
    helping = False
    paused = False
    frame = 0
    fps_est = args.fps
    glitch_until = 0.0
    prev = time.time()
    sim = 0.0
    rng = random.Random()

    def note(kind, text, tone):
        log.append((time.time(), kind, text, tone))
        if len(log) > 400:
            del log[:200]

    while True:
        now = time.time()
        dt = now - prev
        prev = now
        if not paused:
            sim += dt
        if frame and dt > 1e-6:
            fps_est = fps_est * 0.9 + min(1.0 / dt, 999.0) * 0.1
        frame += 1

        for k in kbd.poll():
            if k in ('q', '\x03'):
                cleanup()
            elif k == ' ':
                paused = not paused
            elif k in ('h', '?'):
                helping = not helping
            elif k == 'p':
                pal = PAL_NAMES[(PAL_NAMES.index(pal) + 1) % len(PAL_NAMES)]
            elif k in '12345':
                pal = PAL_NAMES[int(k) - 1]
            elif k == 'n':
                show['night'] = not show['night']
            elif k == 'a':
                show['arcs'] = not show['arcs']
            elif k == 'k':
                show['packets'] = not show['packets']
            elif k == 'g':
                show['glitch'] = not show['glitch']
            elif k == 'l':
                show['labels'] = not show['labels']
            elif k == 's':
                show['sidebar'] = not show['sidebar']
            elif k == 'e':
                show['log'] = not show['log']
            elif k == 'd':
                show['dns'] = not show['dns']
                res.enabled = show['dns']
            elif k == 'm':
                show['private'] = not show['private']
            elif k == 'z':
                z = show['sidebar'] or show['log']
                show['sidebar'] = show['log'] = show['labels'] = not z
            elif k == 'r':
                smp.nudge()
                note('*', 'manual re-scan', 'hud')
            elif k in ('ESC', 'x'):
                sel = None
                hold_until = 0.0
            elif k in ('LEFT', 'RIGHT'):
                sort = (sort + (1 if k == 'RIGHT' else -1)) % len(SORTS)
                hold_until = 0.0            # show the new sort immediately
            elif k in ('UP', 'DOWN') and rowdata:
                # Freeze the ordering for a few seconds: re-sorting under the
                # cursor while you arrow through it makes selection a fight.
                if now >= hold_until:
                    held_rows = rowdata     # freeze values, not just order
                hold_until = now + 3.0
                ips = [d['ip'] for d in rowdata]
                if sel in ips:
                    i = ips.index(sel) + (1 if k == 'DOWN' else -1)
                    sel = ips[i % len(ips)]
                else:
                    sel = ips[0 if k == 'DOWN' else -1]

        # ---- fold the newest snapshot into the endpoint table -------------
        snap = smp.get()
        sid = id(snap)
        if sid != last_sample_id and not paused:
            gap = max(1e-3, now - last_rates) if last_rates else args.interval
            last_rates = now
            last_sample_id = sid
            live = {}
            for key, c in snap.items():
                ip = c['ip']
                if not show['private'] and is_private(ip):
                    continue
                if args.no_udp and c.get('proto') == 'udp':
                    continue
                p = prev_counters.get(key)
                dtx = max(0, c['tx'] - p[0]) if p else 0
                drx = max(0, c['rx'] - p[1]) if p else 0
                e = live.get(ip)
                if e is None:
                    e = live[ip] = {'conns': 0, 'tx': 0, 'rx': 0, 'rtt': 0.0,
                                    'procs': set(), 'ports': set(),
                                    'protos': set(), 'inbound': False,
                                    'st': c['state']}
                e['conns'] += 1
                e['tx'] += dtx
                e['rx'] += drx
                e['procs'].add((c['proc'], c.get('pid', 0)))
                e['ports'].add(c['port'])
                e['protos'].add(c.get('proto', 'tcp'))
                e['inbound'] = e['inbound'] or c.get('inbound', False)
                if c['rtt']:
                    e['rtt'] = c['rtt'] if not e['rtt'] else min(e['rtt'], c['rtt'])
            prev_counters = {k: (v['tx'], v['rx']) for k, v in snap.items()}

            for ip, d in live.items():
                ep = eps.get(ip)
                if ep is None:
                    ep = eps[ip] = Endpoint(ip, now)
                    ep.flash = 1.0
                    port = sorted(d['ports'])[0]
                    svc = PORT_NAMES.get(port, str(port))
                    tone = 'alert' if d['ports'] & NOTABLE else 'hud'
                    pn, pd = sorted(d['procs'])[0]
                    cc = ip_country(ip) or '..'
                    note('<' if d['inbound'] else '>',
                         f'{cc:<3}{ip:<22}{svc:<10}{pn}/{pd}', tone)
                    if cc not in seen_ccs and cc not in ('..', '??'):
                        seen_ccs.add(cc)
                        if not first_scan:
                            cname = CENTROIDS.get(cc, ('', '', cc))[2]
                            note('!', f'FIRST CONTACT  {cc} {cname}', 'alert')
                elif not ep.alive:
                    ep.flash = 1.0
                    note('>', f'{(ep.cc or ".."):<3}{ip:<22}re-established', 'hud')
                ep.alive = True
                ep.last = now
                ep.conns = d['conns']
                ep.tx += d['tx']
                ep.rx += d['rx']
                ep.rate_tx = d['tx'] * 8.0 / gap
                ep.rate_rx = d['rx'] * 8.0 / gap
                ep.rtt = d['rtt'] or ep.rtt
                ep.procs = d['procs']
                ep.ports = d['ports']
                ep.protos = d['protos']
                ep.inbound = d['inbound']
                tot_tx += d['tx']
                tot_rx += d['rx']

            for ip, ep in eps.items():
                if ip not in live and ep.alive:
                    ep.alive = False
                    ep.rate_tx = ep.rate_rx = 0.0
                    note('x', f'{(ep.cc or ".."):<3}{ip:<22}'
                              f'v{size(ep.rx)} ^{size(ep.tx)} in '
                              f'{fmt_dur(now - ep.first)}', 'dim')

            # drop long-dead endpoints so the table can't grow without bound
            for ip in [i for i, e in eps.items()
                       if not e.alive and now - e.last > 45]:
                del eps[ip]
                paths.pop(ip, None)
            first_scan = False
            hist.append((now, len(live)))
            if len(hist) > 400:
                del hist[:200]

        # notable throughput, reported at most once every 20s per endpoint
        for ep in eps.values():
            mag = max(ep.rate_rx, ep.rate_tx)
            if mag > 4e6 and now - burst_at.get(ep.ip, 0) > 20.0:
                burst_at[ep.ip] = now
                way = 'down' if ep.rate_rx >= ep.rate_tx else 'up'
                pn = sorted(ep.procs)[0][0] if ep.procs else '?'
                note('!', f'BURST  {ep.ip} {bps(mag)}bps {way}  {pn}', 'alert')

        # resolve geo lazily as the table becomes available
        for ep in eps.values():
            if ep.cc is None:
                cc = ip_country(ep.ip)
                if cc is not None:
                    ep.cc = cc
                    pos = place(ep.ip, cc)
                    if pos:
                        ep.lat, ep.lon = pos
            if show['dns']:
                host = res.get(ep.ip)
                if host and ep.ip not in named:
                    named.add(ep.ip)
                    note('~', f'{ep.ip:<22}= {host}', 'dim')
            ep.flash *= 0.94 ** (dt * 60)

        # ---- layout ------------------------------------------------------
        cols, rows = shutil.get_terminal_size((100, 30))
        cols = max(40, cols)
        rows = max(12, rows)
        P = PALETTES[pal]
        sw = 0
        if show['sidebar']:
            sw = 38 if cols >= 116 else (34 if cols >= 104 else
                                         (28 if cols >= 88 else 0))
        top = 1 if not args.zen else 0
        map_w = cols - sw
        avail = rows - top
        # A 2:1 world needs ~4 columns per row of terminal cell, so on a tall
        # window the map can't fill the height. Rather than float it in a void,
        # size it to the width and hand every leftover row to the event log.
        uw = map_w
        uh = max(3, uw // 4)
        if uh > avail:
            uh = max(3, avail)
            uw = min(map_w, uh * 4)
        lh = 0
        if show['log']:
            spare = avail - uh
            if spare >= 4:
                lh = spare
            elif avail >= 14:
                lh = 4                      # squeeze the map to keep a log
                uh = max(3, avail - lh)
                uw = min(map_w, uh * 4)
        map_h = avail - lh

        buf = [[' '] * cols for _ in range(rows)]
        fg = [[None] * cols for _ in range(rows)]
        lay = [[0] * cols for _ in range(rows)]

        def put(r, c, ch, color, z=Z_TEXT):
            if 0 <= r < rows and 0 <= c < cols and z >= lay[r][c]:
                buf[r][c] = ch
                fg[r][c] = color
                lay[r][c] = z

        def text(r, c, s, color, limit=None, *, z=Z_TEXT):
            if limit is not None:
                s = s[:limit]
            for i, ch in enumerate(s):
                put(r, c + i, ch, color, z)

        mx = (map_w - uw) // 2
        my = top + (map_h - uh) // 2

        def proj(lat, lon):
            return (my + int((90.0 - lat) / 180.0 * uh),
                    mx + int((lon + 180.0) / 360.0 * uw))

        sdec, slon = subsolar(now)

        # ---- land --------------------------------------------------------
        # Smooth terminator: a 16-stop ramp night -> dusk -> day, built once
        # per frame, so the day/night boundary reads as a gradient rather than
        # three flat bands. Cell coverage picks the glyph weight, which makes
        # continent interiors solid and coastlines feather out.
        grid, coslon, sinlon = land_raster(uw, uh)
        STEPS = 16
        ramp_hi, ramp_lo = [], []
        for k in range(STEPS):
            t = k / (STEPS - 1.0)
            c = (lerp(P['map_night'], P['map_dusk'], t * 2.0) if t < 0.5
                 else lerp(P['map_dusk'], P['map_day'], (t - 0.5) * 2.0))
            ramp_hi.append(quant(c))
            ramp_lo.append(quant(scale(c, 0.88)))
        sd = math.radians(sdec)
        sin_sd, cos_sd = math.sin(sd), math.cos(sd)
        sl = math.radians(slon)
        cos_sl, sin_sl = math.cos(sl), math.sin(sl)
        night = show['night']
        for j, (sin_la, cos_la, cells) in enumerate(grid):
            rr = my + j
            base = my + j
            if not (top <= base < top + map_h):
                continue
            for i, frac in cells:
                if night:
                    # cos(lon - slon) expanded so the loop stays trig-free
                    ca = coslon[i] * cos_sl + sinlon[i] * sin_sl
                    a = sin_la * sin_sd + cos_la * cos_sd * ca
                    t = (a + 0.15) / 0.40
                    k = 0 if t < 0.0 else (STEPS - 1 if t > 1.0
                                           else int(t * (STEPS - 1)))
                else:
                    k = STEPS - 1
                if frac >= 0.75:
                    put(rr, mx + i, ':', ramp_hi[k], Z_LAND)
                elif frac >= 0.40:
                    put(rr, mx + i, '·', ramp_hi[k], Z_LAND)
                else:
                    put(rr, mx + i, '·', ramp_lo[k], Z_LAND)

        # ---- arcs --------------------------------------------------------
        plotted = [e for e in eps.values() if e.lat is not None]
        hr, hc = proj(*home)

        def fade_of(ep):
            """Closed endpoints dim to a still-legible floor, then vanish --
            fading all the way to black just leaves unreadable smudges."""
            if ep.alive:
                return 1.0
            age = now - ep.last
            if age > 10.0:
                return 0.0
            return 1.0 - (1.0 - FADE_DEAD) * min(1.0, age / 4.0)
        if show['arcs'] or sel:
            for ep in plotted:
                # a selected endpoint keeps its arc even with arcs switched off
                if not show['arcs'] and ep.ip != sel:
                    continue
                fade = fade_of(ep)
                if fade <= 0.02:
                    continue
                key = (round(ep.lat, 2), round(ep.lon, 2), uw, uh, home)
                cached = paths.get(ep.ip)
                if cached is None or cached[0] != key:
                    er, ec = proj(ep.lat, ep.lon)
                    n = max(8, int(math.hypot(er - hr, (ec - hc) * 0.5) * 1.6))
                    cached = (key, gc_path(home, (ep.lat, ep.lon), min(n, 240)))
                    paths[ep.ip] = cached
                pts = cached[1]
                hot = (sel == ep.ip)
                base = P['arc'] if not hot else P['pkt_out']
                cells = [proj(la, lo) for la, lo in pts]
                # An idle link draws as a dotted trail and a busy one as a
                # solid line. Weight varies by density, never by dimming --
                # dimming an arc just pushes it under the contrast floor.
                mag = ep.rate_rx + ep.rate_tx
                act = 0.0 if mag <= 0 else min(
                    1.0, max(0.0, math.log10(max(10.0, mag)) - 2.0) / 5.0)
                step = 1 if (hot or act > 0.55) else (2 if act > 0.12 else 3)
                for i, (r, c) in enumerate(cells):
                    if i % step:
                        continue
                    if not (top <= r < top + map_h and 0 <= c < map_w):
                        continue
                    # glyph follows the local slope so the arc reads as a line
                    j = i + 1 if i + 1 < len(cells) else i - 1
                    dr, dc = cells[j][0] - r, cells[j][1] - c
                    if abs(dc) > 180:                 # antimeridian wrap
                        dc = 0
                    if dr == 0:
                        ch = '-'
                    elif dc == 0:
                        ch = '|'
                    elif (dr > 0) == (dc > 0):
                        ch = '\\'
                    else:
                        ch = '/'
                    t = i / max(1, len(cells) - 1)
                    w = 0.62 + 0.30 * math.sin(t * math.pi)
                    if hot:
                        w = 0.72 + 0.28 * math.sin(t * math.pi - sim * 6.0)
                    put(r, c, ch, quant(scale(base, max(FLOOR * 0.8, w * fade))))

        # ---- packets -----------------------------------------------------
        if show['packets'] and not paused:
            for ep in plotted:
                if not ep.alive:
                    continue
                for rate, dr in ((ep.rate_rx, -1), (ep.rate_tx, 1)):
                    if rate <= 0:
                        continue
                    n = min(6.0, 0.6 + math.log10(max(10.0, rate)) * 0.9)
                    if rng.random() < n * dt:
                        packets.append([ep.ip, 0.0, dr, 0.55 + rng.random() * 0.5])
            if len(packets) > 400:
                del packets[:len(packets) - 400]
        for pk in packets:
            pk[1] += dt * pk[3]
        packets = [p for p in packets if p[1] <= 1.0 and p[0] in paths]
        if show['packets']:
            for ip, t, dr, _sp in packets:
                pts = paths[ip][1]
                u = t if dr > 0 else 1.0 - t
                i = int(u * (len(pts) - 1))
                r, c = proj(*pts[max(0, min(len(pts) - 1, i))])
                if top <= r < top + map_h and 0 <= c < map_w:
                    put(r, c, '*' if dr > 0 else 'o',
                        quant(P['pkt_out'] if dr > 0 else P['pkt_in']), Z_PKT)

        # ---- endpoint dots + labels --------------------------------------
        occupied = {}
        pending_labels = []
        by_traffic = sorted(plotted, key=lambda e: -(e.rate_rx + e.rate_tx))
        # Chosen by *cumulative* bytes, which only ever grows -- picking by
        # instantaneous rate made the set churn every scan and the labels
        # flicker on and off.
        labelled = {e.ip for e in sorted(
            (q for q in plotted if q.alive),
            key=lambda e: (-(e.rx + e.tx), e.first))[:6]}
        for ep in by_traffic:
            r, c = proj(ep.lat, ep.lon)
            if not (top <= r < top + map_h and 0 <= c < map_w):
                continue
            fade = fade_of(ep)
            if fade <= 0.02:
                continue
            hot = ep.ports & NOTABLE
            base = P['alert'] if hot else P['node']
            b = 0.82 + 0.18 * math.sin(sim * 3.0 + hash(ep.ip) % 100)
            if ep.flash > 0.02:
                base = P['pkt_out']
                b = 1.0
            ch = 'O' if (ep.rate_rx + ep.rate_tx) > 2e6 else \
                 ('o' if ep.alive else 'x')
            if sel == ep.ip:
                ch = '@'
                b = 1.0
            put(r, c, ch, quant(scale(base, max(FLOOR, b * fade))), Z_NODE)
            occupied[(r, c)] = ep
            # Label a fixed set -- the busiest few plus the selection -- so the
            # same endpoints stay named frame to frame. The old code labelled
            # whichever dot happened to find blank pixels, which is why one
            # endpoint got a name and the rest silently didn't.
            if ep.alive and (sel == ep.ip or
                             (show['labels'] and ep.ip in labelled)):
                pending_labels.append((r, c, ep, fade))

        # ---- home node ---------------------------------------------------
        if top <= hr < top + map_h:
            pulse = 0.6 + 0.4 * math.sin(sim * 2.4)
            put(hr, hc, '#', quant(scale(P['hud'], pulse)))
            occupied[(hr, hc)] = 'home'
            for dr, dc, ch in ((-1, 0, '|'), (1, 0, '|'), (0, -2, '-'), (0, 2, '-')):
                rr, cc2 = hr + dr, hc + dc
                if top <= rr < top + map_h and 0 <= cc2 < map_w and buf[rr][cc2] == ' ':
                    put(rr, cc2, ch, quant(scale(P['hud'], 0.55 + 0.45 * pulse)))
                    occupied[(rr, cc2)] = 'home'

        # ---- endpoint labels ---------------------------------------------
        # Deliberately last: drawn during the node pass they were clobbered by
        # later dots and by THIS NODE, which is why names came out truncated.
        pending_labels.sort(key=lambda t: t[2].ip != sel)
        for r, c, ep, fade in pending_labels:
            nm = res.cache.get(ep.ip) or ''
            nm = nm.split('.')[-2] if nm.count('.') >= 1 else ''
            lab = (nm or ep.cc or '??').upper()[:11]
            for lc in (c + 2, c - 1 - len(lab)):
                if lc < 0 or lc + len(lab) >= map_w:
                    continue
                if any((r, lc + k) in occupied for k in range(len(lab))):
                    continue
                text(r, lc, lab,
                     quant(scale(P['hot'] if sel == ep.ip else P['hud_dim'],
                                 max(FADE_TEXT, fade))), z=Z_TEXT)
                for k in range(len(lab)):
                    occupied[(r, lc + k)] = ep
                break

        # ---- sorting for the panels --------------------------------------
        def sortkey(e):
            if SORTS[sort] == 'traffic':        # right now, bits/sec
                return -(e.rate_rx + e.rate_tx + (1 if e.alive else 0) * 1e-3)
            if SORTS[sort] == 'volume':         # cumulative bytes this session
                return (-(e.rx + e.tx), e.ip)
            if SORTS[sort] == 'recent':
                return -e.last
            if SORTS[sort] == 'latency':
                return (e.rtt or 9e9)
            if SORTS[sort] == 'process':
                # group by app, then by pid within the app; ip only to keep
                # the ordering stable between frames
                pn, pd = min(e.procs) if e.procs else ('~', 0)
                return (pn.lower(), pd, e.ip)
            return (e.cc or 'ZZ', e.ip)

        def snap_row(e):
            """Flat copy of everything the panel draws. While the list is held
            we render from these, so nothing moves, changes or drops out
            mid-selection."""
            return {'ip': e.ip, 'cc': e.cc, 'ports': set(e.ports),
                    'procs': set(e.procs), 'protos': set(e.protos),
                    'rate_rx': e.rate_rx, 'rate_tx': e.rate_tx,
                    'rx': e.rx, 'tx': e.tx, 'rtt': e.rtt, 'alive': e.alive,
                    'inbound': e.inbound, 'conns': e.conns, 'first': e.first,
                    'at': now, 'host': res.cache.get(e.ip)}

        held = bool(now < hold_until and held_rows)
        if held:
            rowdata = held_rows
        else:
            rowdata = [snap_row(e) for e in sorted(eps.values(), key=sortkey)]

        # ---- sidebar -----------------------------------------------------
        if sw:
            x = cols - sw
            for r in range(rows):
                put(r, x - 1, '|', quant(P['rule']))
            live_n = sum(1 for d in rowdata if d['alive'])
            text(top, x + 1, f'ENDPOINTS {live_n:>3}/{len(rowdata):<3}',
                 P['hud'], sw - 2)
            text(top, x + sw - 9,
                 '[ HELD  ]' if held else f'[{SORTS[sort][:7]}]',
                 quant(P['hot'] if held else P['hud_dim']))
            text(top + 1, x + 1, '-' * (sw - 2), quant(P['rule']))
            r = top + 2
            picked = next((d for d in rowdata if d['ip'] == sel), None)
            detail_top = rows - (9 if picked else 0)
            for d in rowdata:
                if r + 1 >= detail_top:
                    break
                fade = 1.0 if d['alive'] else FADE_DEAD
                mark = '>' if sel == d['ip'] else ' '
                cc = d['cc'] or '..'
                tone = P['alert'] if (d['ports'] & NOTABLE) else P['hud']
                port = sorted(d['ports'])[0] if d['ports'] else 0
                svc = PORT_NAMES.get(port, str(port))[:8]
                dirn = '<' if d['inbound'] else ' '
                ip = d['ip']
                ips = ip if len(ip) <= sw - 13 else ip[:sw - 14] + '~'
                text(r, x + 1, f'{mark}{dirn}{cc} {ips}',
                     quant(scale(tone, fade)), sw - 10)
                text(r, x + sw - 9, svc.rjust(8),
                     quant(scale(P['hud_dim'], fade)))
                if r + 1 < detail_top:
                    pn, pd = (sorted(d['procs'])[0] if d['procs'] else ('?', 0))
                    more = f'+{len(d["procs"]) - 1}' if len(d['procs']) > 1 else ''
                    who = f'{pn[:9]}/{pd}{more}'
                    rtt = f'{d["rtt"]:4.0f}ms' if d['rtt'] else '  -- '
                    if SORTS[sort] == 'volume':
                        # show the quantity being sorted on, or the ordering
                        # looks arbitrary against a column of live rates
                        flow = f'v{size(d["rx"]):>6} ^{size(d["tx"]):>6}'
                    elif d['rate_rx'] or d['rate_tx']:
                        flow = f'v{bps(d["rate_rx"])} ^{bps(d["rate_tx"])}'
                    elif d['rx'] or d['tx']:    # idle: fall back to lifetime
                        flow = f' {bps(d["rx"] * 8)}  {bps(d["tx"] * 8)}'
                    else:
                        flow = '     idle      '
                    mag = max(d['rate_rx'], d['rate_tx'])
                    heat = 0.0 if mag <= 0 else min(
                        1.0, max(0.0, math.log10(max(10.0, mag)) - 2.0) / 5.0)
                    stat = lerp(P['hud_dim'], P['hot'], heat)
                    text(r + 1, x + 1, f'{flow} {rtt} {who}',
                         quant(scale(stat, fade)), sw - 2)
                r += 2

            # ---- selected endpoint: everything known about it -------------
            if picked:
                d = picked
                dr = rows - 9
                text(dr, x + 1, '-' * (sw - 2), quant(P['rule']))
                cname = CENTROIDS.get(d['cc'] or '', ('', '', 'UNKNOWN'))[2]
                text(dr + 1, x + 1, d['ip'][:sw - 2], P['hot'])
                text(dr + 2, x + 1, f'{d["cc"] or "??"} {cname}'[:sw - 2],
                     quant(P['hud']))
                if not show['dns']:
                    host, hcol = 'rDNS disabled (d)', P['rule']
                else:
                    nm = d['host']
                    if nm is None:
                        host, hcol = 'resolving...', P['rule']
                    elif nm == '':
                        host, hcol = 'no PTR record', P['rule']
                    else:
                        host, hcol = nm, P['hud_dim']
                text(dr + 3, x + 1, host[:sw - 2], quant(hcol))
                svcs = ' '.join(PORT_NAMES.get(q, str(q))
                                for q in sorted(d['ports'])[:3])
                proto = '+'.join(sorted(d['protos'])) or 'tcp'
                arrow = 'INBOUND' if d['inbound'] else 'outbound'
                text(dr + 4, x + 1, f'{proto} {arrow} {svcs}'[:sw - 2],
                     quant(P['alert'] if d['inbound'] else P['hud_dim']))
                who = ', '.join(f'{n}/{i}' for n, i in sorted(d['procs'])[:2])
                text(dr + 5, x + 1, who[:sw - 2], quant(P['hud_dim']))
                text(dr + 6, x + 1,
                     f'{d["conns"]} conn  v{size(d["rx"])} ^{size(d["tx"])}'[:sw - 2],
                     quant(P['hud_dim']))
                age = fmt_dur(d['at'] - d['first'])
                text(dr + 7, x + 1,
                     (f'rtt {d["rtt"]:.0f}ms  up {age}' if d['rtt']
                      else f'up {age}'),
                     quant(P['hud_dim']), sw - 2)

        # ---- event log ---------------------------------------------------
        if lh:
            ly = rows - lh
            for c in range(cols - sw):
                put(ly, c, '-', quant(P['rule']))
            text(ly, 2, ' EVENT LOG ', quant(P['hud_dim']))
            width = cols - sw - 2
            for i, (t, kind, msg, tone) in enumerate(log[-(lh - 1):]):
                col = {'alert': P['alert'], 'hud': P['hud'],
                       'dim': P['hud_dim']}.get(tone, P['hud_dim'])
                age = min(1.0, (now - t) / 25.0)
                f = 1.0 - (1.0 - FADE_TEXT) * age
                stamp = time.strftime('%H:%M:%S', time.localtime(t))
                ry = ly + 1 + i
                # timestamp / marker / message each get their own weight so a
                # wall of log lines has some texture to it
                text(ry, 1, stamp, quant(scale(P['rule'], 0.85 + 0.15 * f)))
                mcol = {'>': P['hot'], '<': P['alert'], '!': P['alert'],
                        'x': P['rule'], '~': P['hud_dim']}.get(kind, col)
                text(ry, 10, kind, quant(scale(mcol, f)))
                text(ry, 12, msg, quant(scale(col, f)), width - 12)

        # ---- status bar --------------------------------------------------
        if not args.zen:
            live_n = sum(1 for e in eps.values() if e.alive)
            ccs = len({e.cc for e in eps.values() if e.alive and e.cc})
            rx = sum(e.rate_rx for e in eps.values() if e.alive)
            tx = sum(e.rate_tx for e in eps.values() if e.alive)
            peak_rx = max(peak_rx, rx)
            peak_tx = max(peak_tx, tx)
            # most-important-first, so narrow terminals drop the tail
            bits = [
                'NETMAP',
                f'{live_n:>3} NODE',
                f'{sum(e.conns for e in eps.values() if e.alive):>3} CONN',
                f'v{bps(rx)}bps ^{bps(tx)}bps',
                f'TOTAL v{size(tot_rx)} ^{size(tot_tx)}',
                f'{ccs:>2} CC',
                'PAUSED' if paused else fmt_dur(now - started),
                (smp.method or 'init').upper(),
                f'{fps_est:4.0f}fps',
                f'peak v{bps(peak_rx)} ^{bps(peak_tx)}',
                f'SUN {sdec:+05.1f} {slon:+06.1f}',
                'GEO' if _GEO['ready'] else 'GEO..',
            ]
            room = cols - 10
            s = ''
            for b in bits:
                nxt = b if not s else s + ' | ' + b
                if len(nxt) > room:
                    break
                s = nxt
            text(0, 1, s, P['alert'] if paused else P['hud'], room)
            text(0, cols - 8, 'h:help', quant(P['hud_dim']))
            if smp.err:
                text(1, 2, f'SAMPLER: {smp.err}'[:cols - 4], P['alert'])

        # ---- open-connection history strip -------------------------------
        # Rides the event-log rule when there is one; the map is too busy to
        # overlay it on, and a half-occluded sparkline reads as noise.
        if not args.zen and len(hist) > 2 and map_w > 40:
            ramp = ' ▁▂▃▄▅▆▇█'
            peak = max(1, max(h[1] for h in hist[-90:]))
            width_avail = map_w - 24
            n = min(len(hist), max(10, min(60, width_avail)))
            bars = [h[1] for h in hist[-n:]]
            spark = ''.join(ramp[min(8, int(v / peak * 8))] for v in bars)
            label = f'{bars[-1]}/{peak} OPEN '
            sy = rows - lh if lh else top + map_h - 1
            lx = max(0, map_w - (len(spark) + len(label) + 2))
            if not lh:                      # no log: clear a slot in the map
                for k in range(lx, map_w):
                    put(sy, k, ' ', None)
            text(sy, lx, label, quant(P['hud_dim']))
            for i, ch in enumerate(spark):
                put(sy, lx + len(label) + i, ch,
                    quant(lerp(P['hud_dim'], P['hot'], bars[i] / peak)))

        # ---- glitch ------------------------------------------------------
        if show['glitch'] and not paused:
            if now > glitch_until and rng.random() < 0.004:
                glitch_until = now + rng.uniform(0.05, 0.22)
            if now < glitch_until:
                for _ in range(rng.randint(6, 26)):
                    r = rng.randrange(top, rows)
                    c = rng.randrange(0, cols)
                    put(r, c, rng.choice('#@%&$?/\\|_01'),
                        quant(scale(P['alert'], rng.uniform(0.4, 1.0))))
                gr = rng.randrange(top, rows)
                shift = rng.randint(-3, 3)
                if shift:
                    buf[gr] = buf[gr][-shift:] + buf[gr][:-shift]
                    fg[gr] = fg[gr][-shift:] + fg[gr][:-shift]

        # ---- help overlay ------------------------------------------------
        if helping:
            w = max(len(l) for l in HELP_LINES) + 2
            w = min(w, cols - 4)
            h = len(HELP_LINES)
            y0 = max(0, (rows - h) // 2)
            x0 = max(0, (cols - w) // 2)
            for i in range(h):
                for j in range(w):
                    put(y0 + i, x0 + j, ' ', None)
            for i, line in enumerate(HELP_LINES):
                tone = P['hud'] if i < 3 else quant(P['hud_dim'])
                text(y0 + i, x0 + 1, line, tone, w - 2)
            for j in range(w):
                put(y0, x0 + j, '-', quant(P['rule']))
                put(y0 + h - 1, x0 + j, '-', quant(P['rule']))

        # ---- emit --------------------------------------------------------
        out = [HOME]
        cur = None
        for r in range(rows):
            out.append(f'{ESC}{r + 1};1H')
            for c in range(cols):
                col = fg[r][c]
                if col is not None and col != cur:
                    out.append(sgr(col))
                    cur = col
                out.append(buf[r][c])
            out.append(ESC + 'K')
        out.append(RESET)
        sys.stdout.write(''.join(out))
        sys.stdout.flush()

        target = 1.0 / max(1.0, args.fps)
        slack = target - (time.time() - now)
        if slack > 0:
            time.sleep(slack)


if __name__ == '__main__':
    main()
